/**
 * @ingroup iface_zcr_toast_surface_v2
 * @struct zcr_toast_surface_v2_interface
 */
struct zcr_toast_surface_v2_interface {
	/**
	 * Destroy the toast_surface
	 *
	 * Unmap and destroy the toast surface.
	 */
	void (*destroy)(struct wl_client *client,
			struct wl_resource *resource);
	/**
	 * set toast bounds position
	 *
	 * Set the bounds of a toast window from the user's perspective.
	 *
	 * The bounds are double buffered, and will be applied at the time
	 * wl_surface.commit of the corresponding wl_surface is called.
	 *
	 * Once the bounds are set, it is not possible to unset them, and
	 * they will remain the same until set_bounds is called again, even
	 * if a new sub- surface or buffer is attached.
	 *
	 * If never set, the compositor will determine the toast position.
	 *
	 * The bounds are relative to the given display. If the display is
	 * invalid, they are assumed to be relative to the primary display.
	 */
	void (*set_bounds_in_output)(struct wl_client *client,
				     struct wl_resource *resource,
				     struct wl_resource *output,
				     int32_t x,
				     int32_t y,
				     int32_t width,
				     int32_t height);
	/**
	 * Allows the client to set the scale factor for the future buffer commits.
	 *
	 * The client has a 32-bit float scale factor that is associated
	 * with each remote surface. This scale factor must be propagated
	 * exactly to exo. To do so we reinterpret_cast into a 32-bit uint
	 * and later cast back into a float. This is because wayland does
	 * not support native transport of floats. As different CPU
	 * architectures may use different endian representations for IEEE
	 * 754 floats, this protocol implicitly assumes that the caller and
	 * receiver are the same machine. This is double buffered state and
	 * will be applied in the next commit.
	 * @since 2
	 */
	void (*set_scale_factor)(struct wl_client *client,
				 struct wl_resource *resource,
				 uint32_t scale_factor_as_uint);
};


